import math

def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def get_divisors(n):
    factors = prime_factorization(n)
    divisors = set()
    primes = list(factors.keys())

    def generate(index, current_divisor):
        if index == len(primes):
            divisors.add(current_divisor)
            return

        p = primes[index]
        max_exp = factors[p]

        power_of_p = 1
        for exp in range(max_exp + 1):
            generate(index + 1, current_divisor * power_of_p)
            power_of_p *= p

    generate(0, 1)
    return sorted(list(divisors))

N = 2021
divs = get_divisors(N)
print(f"Divisors of {N}: {divs}")
print(f"Possible sizes (|K| >= 3): {[d for d in divs if d >= 3]}")
